public void onUpdate(){

	// Bit of a cheat but it's easier than trying to sync FrostBarrier#addConstructExtras
	if(world.isRemote && firstUpdate){
		setSizeMultiplier(sizeMultiplier); // Do this first or it'll overwrite the bounding box
		setRotation(rotationYaw, rotationPitch);
	}

	this.prevPosX = posX;
	this.prevPosY = posY;
	this.prevPosZ = posZ;

	if(!world.isRemote){

		double extensionSpeed = 0;

		if(lifetime - this.ticksExisted < 20){
			extensionSpeed = -0.01 * (this.ticksExisted - (lifetime - 20)) * sizeMultiplier;
		}else if(ticksExisted > 3 + delay){
			extensionSpeed = 0;
		}else if(ticksExisted > delay){
			extensionSpeed = 0.5 * sizeMultiplier;
		}

		this.move(MoverType.SELF, 0, extensionSpeed, 0);
	}

	if(ticksExisted == delay + 1) this.playSound(WizardrySounds.ENTITY_ICE_BARRIER_EXTEND, 1, 1.5f);

	super.onUpdate();

	Vec3d look = this.getLookVec();

	if(!world.isRemote){

		for(Entity entity : world.getEntitiesWithinAABBExcludingEntity(this, getEntityBoundingBox().grow(2))){

			if(entity instanceof EntityMagicConstruct) continue;

			if(!entity.getEntityBoundingBox().intersects(this.getEntityBoundingBox())) continue;

			// For some reason the player position seems to be off by 1 block in x and z, no idea how so for now
			// I've just fudged it by adding 1 to x and z
			double perpendicularDist = getSignedPerpendicularDistance(entity.getPositionVector().add(1, 0, 1));

			if(Math.abs(perpendicularDist) < entity.width/2 + THICKNESS/2){

				double velocity = 0.25 * Math.signum(perpendicularDist);
				entity.addVelocity(velocity * look.x, 0, velocity * look.z);
				// Player motion is handled on that player's client so needs packets
				if(entity instanceof EntityPlayerMP){
					((EntityPlayerMP)entity).connection.sendPacket(new SPacketEntityVelocity(entity));
				}
			}
		}
	}

}

public boolean attackEntityFrom(DamageSource source, float amount){
	this.playSound(WizardrySounds.ENTITY_ICE_BARRIER_DEFLECT, 0.7f, 2.5f);
	return super.attackEntityFrom(source, amount);
}

	public Vec3d calculateIntercept(Vec3d origin, Vec3d endpoint, float fuzziness){
		// Calculate the point at which the line intersects the barrier plane
		Vec3d vec = endpoint.subtract(origin);

		double perpendicularDist = getPerpendicularDistance(origin);
		double perpendicularDist2 = getPerpendicularDistance(endpoint);

		Vec3d intercept = origin.add(vec.scale(perpendicularDist / (perpendicularDist + perpendicularDist2)));

		// This seems to be all over the palce, but the calculation MUST be right because it works for entity collisions!
//		world.spawnParticle(EnumParticleTypes.END_ROD, intercept.x, intercept.y, intercept.z, 0, 0, 0);

		// If the point is within the hitbox (expanded by the fuzziness), it was a hit
		return getEntityBoundingBox().grow(fuzziness).contains(intercept) ? intercept : null;
	}

public boolean contains(Vec3d point){
	return this.getEntityBoundingBox().contains(point) && getPerpendicularDistance(point) < THICKNESS/2;
}

private double getSignedPerpendicularDistance(Vec3d point){
	Vec3d look = this.getLookVec();
	Vec3d delta = new Vec3d(point.x - this.posX, 0, point.z - this.posZ);
	return delta.dotProduct(look);
}

private double getPerpendicularDistance(Vec3d point){
	return Math.abs(getSignedPerpendicularDistance(point));
}

public void setRotation(float yaw, float pitch){
	super.setRotation(yaw, pitch);
	float a = MathHelper.cos((float)Math.toRadians(rotationYaw));
	float b = MathHelper.sin((float)Math.toRadians(rotationYaw));
	double x = width/2 * a + THICKNESS/2 * b;
	double z = width/2 * b + THICKNESS/2 * a;
	setEntityBoundingBox(new AxisAlignedBB(this.posX - x, this.posY, this.posZ - z, this.posX + x, this.posY + height, this.posZ + z));
}

public void setDelay(int delay){
	this.delay = delay;
	this.lifetime += delay;
}

protected void readEntityFromNBT(NBTTagCompound nbt){
	super.readEntityFromNBT(nbt);
	delay = nbt.getInteger("delay");
}

protected void writeEntityToNBT(NBTTagCompound nbt){
	super.writeEntityToNBT(nbt);
	nbt.setInteger("delay", delay);
}

package electroblob.wizardry.spell;

import electroblob.wizardry.constants.Constants;
import electroblob.wizardry.entity.construct.EntityIceBarrier;
import electroblob.wizardry.item.SpellActions;
import electroblob.wizardry.registry.WizardryItems;
import electroblob.wizardry.util.BlockUtils;
import electroblob.wizardry.util.GeometryUtils;
import electroblob.wizardry.util.SpellModifiers;
import net.minecraft.entity.EntityLiving;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.tileentity.TileEntityDispenser;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.EnumFacing.Axis;
import net.minecraft.util.EnumHand;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.util.math.Vec3d;
import net.minecraft.world.World;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.List;

public class FrostBarrier extends Spell {

	private static final double BARRIER_DISTANCE = 2;
	private static final double BARRIER_ARC_RADIUS = 10;
	private static final double BARRIER_SPACING = 1.4;

	public FrostBarrier(){
		super("frost_barrier", SpellActions.SUMMON, false);
		this.npcSelector((e, o) -> true);
		addProperties(DURATION);
	}

	@Override
	public boolean canBeCastBy(TileEntityDispenser dispenser){
		return true;
	}

	@Override
	public boolean requiresPacket(){
		return false;
	}

	@Override
	public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

		if(caster.onGround){
			if(!createBarriers(world, caster.getPositionVector(), caster.getLookVec(), caster, modifiers)) return false;
			this.playSound(world, caster, ticksInUse, -1, modifiers);
			return true;
		}

		return false;
	}

	@Override
	public boolean cast(World world, EntityLiving caster, EnumHand hand, int ticksInUse, EntityLivingBase target, SpellModifiers modifiers){

		if(caster.onGround){
			if(!createBarriers(world, caster.getPositionVector(), target.getPositionVector().subtract(caster.getPositionVector()),
					caster, modifiers)) return false;
			this.playSound(world, caster, ticksInUse, -1, modifiers);
			return true;
		}

		return false;
	}

	@Override
	public boolean cast(World world, double x, double y, double z, EnumFacing direction, int ticksInUse, int duration, SpellModifiers modifiers){
		if(!createBarriers(world, new Vec3d(x, y, z), new Vec3d(direction.getDirectionVec()), null, modifiers)) return false;
		// This MUST be the coordinates of the actual dispenser, so we need to offset it
		this.playSound(world, x - direction.getXOffset(), y - direction.getYOffset(), z - direction.getZOffset(), ticksInUse, duration, modifiers);
		return true;
	}

	private boolean createBarriers(World world, Vec3d origin, Vec3d direction, @Nullable EntityLivingBase caster, SpellModifiers modifiers){

		if(!world.isRemote){

			direction = GeometryUtils.horizontalise(direction);
			Vec3d centre = origin.add(direction.scale(BARRIER_DISTANCE - BARRIER_ARC_RADIUS)); // Arc centred behind caster

			// Don't spawn them yet or the anti-overlap will prevent the rest from spawning
			List<EntityIceBarrier> barriers = new ArrayList<>();

			int barrierCount = 1 + Math.max(1, (int)((modifiers.get(SpellModifiers.POTENCY) - 1) / Constants.POTENCY_INCREASE_PER_TIER + 0.5f));

			for(int i = 0; i < barrierCount; i++){

				EntityIceBarrier barrier = createBarrier(world, centre, direction.rotateYaw((float)(BARRIER_SPACING / BARRIER_ARC_RADIUS) * i), caster, modifiers, barrierCount, i);
				if(barrier != null) barriers.add(barrier);

				if(i == 0) continue; // Only one in the middle
				barrier = createBarrier(world, centre, direction.rotateYaw(-(float)(BARRIER_SPACING / BARRIER_ARC_RADIUS) * i), caster, modifiers, barrierCount, i);
				if(barrier != null) barriers.add(barrier);
			}

			if(barriers.isEmpty()) return false;

			barriers.forEach(world::spawnEntity); // Finally spawn them all
		}

		return true;
	}

	private EntityIceBarrier createBarrier(World world, Vec3d centre, Vec3d direction, @Nullable EntityLivingBase caster, SpellModifiers modifiers, int barrierCount, int index){

		Vec3d position = centre.add(direction.scale(BARRIER_ARC_RADIUS));
		Integer floor = BlockUtils.getNearestFloor(world, new BlockPos(position), 3);
		if(floor == null) return null;
		position = GeometryUtils.replaceComponent(position, Axis.Y, floor);

		float scale = 1.5f - (float)index/barrierCount * 0.5f;
		double yOffset = 1.5 * scale;

		EntityIceBarrier barrier = new EntityIceBarrier(world);
		barrier.setPosition(position.x, position.y - yOffset, position.z);
		barrier.setCaster(caster);
		barrier.lifetime = (int)(getProperty(DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));
		barrier.damageMultiplier = modifiers.get(SpellModifiers.POTENCY);
		barrier.setRotation((float)Math.toDegrees(MathHelper.atan2(-direction.x, direction.z)), barrier.rotationPitch);
		barrier.setSizeMultiplier(scale);
		barrier.setDelay(1 + 3 * index); // Delay 0 seems to move it down 1 block, no idea why

		if(!world.getEntitiesWithinAABB(barrier.getClass(), barrier.getEntityBoundingBox().offset(0, yOffset, 0)).isEmpty()) return null;

		return barrier;
	}

}

package electroblob.wizardry.entity.construct;

import electroblob.wizardry.Wizardry;
import electroblob.wizardry.item.ISpellCastingItem;
import electroblob.wizardry.registry.WizardrySounds;
import electroblob.wizardry.util.AllyDesignationSystem;
import electroblob.wizardry.util.EntityUtils;
import io.netty.buffer.ByteBuf;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.IEntityOwnable;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumActionResult;
import net.minecraft.util.EnumHand;
import net.minecraft.util.SoundCategory;
import net.minecraft.util.math.Vec3d;
import net.minecraft.world.World;
import net.minecraftforge.fml.common.registry.IEntityAdditionalSpawnData;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;

import javax.annotation.Nullable;
import java.util.UUID;

/**
 * This class is for all inanimate magical constructs which are not projectiles. Generally speaking, subclasses of this
 * class are areas of effect which deal damage or apply effects over time, including black hole, blizzard, tornado and
 * a few others. The caster UUID, lifetime and damage multiplier are stored here, and lifetime is also synced here.
 *
 * @since Wizardry 1.0
 */
public abstract class EntityMagicConstruct extends Entity implements IEntityOwnable, IEntityAdditionalSpawnData {

	/** The UUID of the caster. As of Wizardry 4.3, this <b>is</b> synced, and rather than storing the caster
	 * instance via a weak reference, it is fetched from the UUID each time it is needed in
	 * {@link EntityMagicConstruct#getCaster()}. */
	private UUID casterUUID;

	/** The time in ticks this magical construct lasts for; defaults to 600 (30 seconds). If this is -1 the construct
	 * doesn't despawn. */
	public int lifetime = 600;

	/** The damage multiplier for this construct, determined by the wand with which it was cast. */
	public float damageMultiplier = 1.0f;

	public EntityMagicConstruct(World world){
		super(world);
		this.height = 1.0f;
		this.width = 1.0f;
		this.noClip = true;
	}

	// Overrides the original to stop the entity moving when it intersects stuff. The default arrow does this to allow
	// it to stick in blocks.
	@Override
	@SideOnly(Side.CLIENT)
	public void setPositionAndRotationDirect(double x, double y, double z, float yaw, float pitch, int posRotationIncrements, boolean teleport){
		this.setPosition(x, y, z);
		this.setRotation(yaw, pitch);
	}

	public void onUpdate(){

		if(this.ticksExisted > lifetime && lifetime != -1){
			this.despawn();
		}

		super.onUpdate();

	}

	@Override
	public EnumActionResult applyPlayerInteraction(EntityPlayer player, Vec3d vec, EnumHand hand){

		// Permanent constructs can now be dispelled by sneak-right-clicking
		if(lifetime == -1 && getCaster() == player && player.isSneaking() && player.getHeldItem(hand).getItem() instanceof ISpellCastingItem){
			this.despawn();
			return EnumActionResult.SUCCESS;
		}

		return super.applyPlayerInteraction(player, vec, hand);
	}

	/**
	 * Defaults to just setDead() in EntityMagicConstruct, but is provided to allow subclasses to override this e.g.
	 * bubble uses it to dismount the entity inside it and play the 'pop' sound before calling super(). You should
	 * always call super() when overriding this method, in case it changes. There is no need, therefore, to call
	 * setDead() when overriding.
	 */
	public void despawn(){
		this.setDead();
	}

	@Override
	protected void entityInit(){
		// We could leave this unimplemented, but since the majority of subclasses don't use it, let's make it optional
	}

	@Override
	protected void readEntityFromNBT(NBTTagCompound nbttagcompound){
		if(nbttagcompound.hasUniqueId("casterUUID")) casterUUID = nbttagcompound.getUniqueId("casterUUID");
		lifetime = nbttagcompound.getInteger("lifetime");
		damageMultiplier = nbttagcompound.getFloat("damageMultiplier");
	}

	@Override
	protected void writeEntityToNBT(NBTTagCompound nbttagcompound){
		if(casterUUID != null){
			nbttagcompound.setUniqueId("casterUUID", casterUUID);
		}
		nbttagcompound.setInteger("lifetime", lifetime);
		nbttagcompound.setFloat("damageMultiplier", damageMultiplier);
	}

	@Override
	public void writeSpawnData(ByteBuf data){
		data.writeInt(lifetime);
		data.writeInt(getCaster() == null ? -1 : getCaster().getEntityId());
	}

	@Override
	public void readSpawnData(ByteBuf data){

		lifetime = data.readInt();

		int id = data.readInt();

		if(id == -1){
			setCaster(null);
		}else{
			Entity entity = world.getEntityByID(id);
			if(entity instanceof EntityLivingBase){
				setCaster((EntityLivingBase)entity);
			}else{
				Wizardry.logger.warn("Construct caster with ID in spawn data not found");
			}
		}
	}

	@Nullable
	@Override
	public UUID getOwnerId(){
		return casterUUID;
	}

	@Nullable
	@Override
	public Entity getOwner(){
		return getCaster(); // Delegate to getCaster
	}

	/**
	 * Returns the EntityLivingBase that created this construct, or null if it no longer exists. Cases where the entity
	 * may no longer exist are: entity died or was deleted, mob despawned, player logged out, entity teleported to
	 * another dimension, or this construct simply had no caster in the first place.
	 */
	@Nullable
	public EntityLivingBase getCaster(){ // Kept despite the above method because it returns an EntityLivingBase

		Entity entity = EntityUtils.getEntityByUUID(world, getOwnerId());

		if(entity != null && !(entity instanceof EntityLivingBase)){ // Should never happen
			Wizardry.logger.warn("{} has a non-living owner!", this);
			entity = null;
		}

		return (EntityLivingBase)entity;
	}

	public void setCaster(@Nullable EntityLivingBase caster){
		this.casterUUID = caster == null ? null : caster.getUniqueID();
	}

	/**
	 * Shorthand for {@link AllyDesignationSystem#isValidTarget(Entity, Entity)}, with the owner of this construct as the
	 * attacker. Also allows subclasses to override it if they wish to do so.
	 */
	public boolean isValidTarget(Entity target){
		return AllyDesignationSystem.isValidTarget(this.getCaster(), target);
	}

	@Override
	public SoundCategory getSoundCategory(){
		return WizardrySounds.SPELLS;
	}

	@Override
	public boolean canRenderOnFire(){
		return false;
	}

	@Override
	public boolean isPushedByWater(){
		return false;
	}
}

package electroblob.wizardry.entity.construct;

import io.netty.buffer.ByteBuf;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.world.World;

/**
 * Extension of {@link EntityMagicConstruct} that implements saving and loading of size (blast) multipliers. What
 * the entity actually does with the multiplier value is up to subclasses to define; however, by default this class
 * scales the entity bounding box according to the size multiplier (this can be controlled by overriding
 * {@link EntityScaledConstruct#shouldScaleWidth()} and {@link EntityScaledConstruct#shouldScaleHeight()}).
 *
 * @author Electroblob
 * @since Wizardry 4.3
 */
public abstract class EntityScaledConstruct extends EntityMagicConstruct {

	/** The size multiplier for this construct, usually determined by the blast modifier the spell was cast with. */
	protected float sizeMultiplier = 1;

	public EntityScaledConstruct(World world){
		super(world);
	}

	public float getSizeMultiplier(){
		return sizeMultiplier;
	}

	public void setSizeMultiplier(float sizeMultiplier){
		this.sizeMultiplier = sizeMultiplier;
		setSize(shouldScaleWidth() ? width * sizeMultiplier : width, shouldScaleHeight() ? height * sizeMultiplier : height);
	}

	/** Returns true if the width of this entity's bounding box should be scaled by the size multiplier on creation. */
	protected boolean shouldScaleWidth(){
		return true;
	}

	/** Returns true if the height of this entity's bounding box should be scaled by the size multiplier on creation. */
	protected boolean shouldScaleHeight(){
		return true;
	}

	@Override
	protected void readEntityFromNBT(NBTTagCompound nbt){
		super.readEntityFromNBT(nbt);
		setSizeMultiplier(nbt.getFloat("sizeMultiplier"));
	}

	@Override
	protected void writeEntityToNBT(NBTTagCompound nbt){
		super.writeEntityToNBT(nbt);
		nbt.setFloat("sizeMultiplier", sizeMultiplier);

	}

	@Override
	public void readSpawnData(ByteBuf data){
		super.readSpawnData(data);
		setSizeMultiplier(data.readFloat()); // Set the width correctly on the client side
	}

	@Override
	public void writeSpawnData(ByteBuf data){
		super.writeSpawnData(data);
		data.writeFloat(sizeMultiplier);
	}
}

package electroblob.wizardry.client.renderer.entity;

import electroblob.wizardry.Wizardry;
import electroblob.wizardry.client.model.ModelIceBarrier;
import electroblob.wizardry.entity.construct.EntityIceBarrier;
import net.minecraft.client.renderer.GlStateManager;
import net.minecraft.client.renderer.entity.Render;
import net.minecraft.client.renderer.entity.RenderManager;
import net.minecraft.util.ResourceLocation;

public class RenderIceBarrier extends Render<EntityIceBarrier> {

	private static final ResourceLocation TEXTURE = new ResourceLocation(Wizardry.MODID, "textures/entity/ice_barrier.png");

	private ModelIceBarrier model = new ModelIceBarrier();

	public RenderIceBarrier(RenderManager manager){
		super(manager);
	}

	@Override
	public void doRender(EntityIceBarrier entity, double x, double y, double z, float yaw, float partialTicks){

		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y + entity.height/2, z);
		GlStateManager.rotate(180, 0F, 0F, 1F);
		GlStateManager.rotate(yaw, 0, 1, 0);
		GlStateManager.translate(0, -entity.height/2 - 0.3, 0);

		float s = entity.getSizeMultiplier();
		GlStateManager.scale(s, s, s);

		this.bindTexture(TEXTURE);

		model.render(entity, 0, 0, 0, 0, 0, 0.0625f);

		GlStateManager.popMatrix();
	}

	@Override
	protected ResourceLocation getEntityTexture(EntityIceBarrier entity){
		return TEXTURE;
	}

}

package electroblob.wizardry.entity;

import net.minecraft.util.math.Vec3d;

/** This interface allows implementing entity classes to define their own hitbox for wizardry's raytracing and
 * particle collision methods. Typically, entities implementing this interface will return null from the collision
 * bounding box methods in {@code Entity} (there are two for some reason) <b>but</b> return true from
 * {@link net.minecraft.entity.Entity#canBeCollidedWith()} */
public interface ICustomHitbox {

	/**
	 * Calculates the point at which the line starting at the given origin and ending at the given endpoint hits this
	 * entity, if any. Used in raytracing to allow entities to define fully custom behaviour. See
	 * {@link electroblob.wizardry.entity.construct.EntityForcefield} for an example implementation of a spherical hitbox.
	 * @param origin The origin of the line.
	 * @param endpoint The endpoint of the line.
	 * @param fuzziness Maximum distance around the line that should still count as a hit.
	 * @return A {@link Vec3d} representing the point hit, or null if there is no intercept. This should be the first
	 * point that the line hits, i.e. if there is more than one intercept this method should return the one nearest to
	 * the given origin.
	 */
	Vec3d calculateIntercept(Vec3d origin, Vec3d endpoint, float fuzziness);

	/**
	 * Returns whether the given point is inside this entity.
	 * @param point The coordinates to test.
	 * @return True if the point is inside this entity, false if not.
	 */
	boolean contains(Vec3d point);

}

public static RayTraceResult rayTrace(World world, Vec3d origin, Vec3d endpoint, float aimAssist,
									  boolean hitLiquids, boolean ignoreUncollidables, boolean returnLastUncollidable, Class<? extends Entity> entityType, Predicate<? super Entity> filter){

	// 1 is the standard amount of extra search volume, and aim assist needs to increase this further as well as
	// expanding the entities' bounding boxes.
	float borderSize = 1 + aimAssist;

	// The AxisAlignedBB constructor accepts min/max coords in either order.
	AxisAlignedBB searchVolume = new AxisAlignedBB(origin.x, origin.y, origin.z, endpoint.x, endpoint.y, endpoint.z)
			.grow(borderSize, borderSize, borderSize);

	// Gets all of the entities in the bounding box that could be collided with.
	List<Entity> entities = world.getEntitiesWithinAABB(entityType, searchVolume);
	// Applies the given filter to remove entities that should be ignored.
	entities.removeIf(filter);

	// Finds the first block hit by the ray trace, if any.
	RayTraceResult result = world.rayTraceBlocks(origin, endpoint, hitLiquids, ignoreUncollidables, returnLastUncollidable);

	// Clips the entity search range to the part of the ray trace before the block hit, if it hit a block.
	if(result != null){
		endpoint = result.hitVec;
	}

	// Search variables
	Entity closestHitEntity = null;
	Vec3d closestHitPosition = endpoint;
	AxisAlignedBB entityBounds;
	Vec3d intercept = null;

	// Iterates through all the entities
	for(Entity entity : entities){

		// I'd like to add the following line so we can, for example, use greater telekinesis through a
		// ring of fire, but doing so will stop forcefields blocking particles
		//if(!entity.canBeCollidedWith()) continue;

		float fuzziness = EntityUtils.isLiving(entity) ? aimAssist : 0; // Only living entities have aim assist

		if(entity instanceof ICustomHitbox){ // Custom hitboxes
			intercept = ((ICustomHitbox)entity).calculateIntercept(origin, endpoint, fuzziness);

		}else{ // Normal hit detection

			entityBounds = entity.getEntityBoundingBox();

			if(entityBounds != null){

				// This is zero for everything except fireballs...
				float entityBorderSize = entity.getCollisionBorderSize();
				// ... meaning the following line does nothing in all other cases.
				// -> Added the non-zero check to prevent unnecessary AABB object creation.
				if(entityBorderSize != 0)
					entityBounds = entityBounds.grow(entityBorderSize, entityBorderSize, entityBorderSize);

				// Aim assist expands the bounding box to hit entities within the specified distance of the ray trace.
				if(fuzziness != 0) entityBounds = entityBounds.grow(fuzziness, fuzziness, fuzziness);

				// Finds the first point at which the ray trace intercepts the entity's bounding box, if any.
				RayTraceResult hit = entityBounds.calculateIntercept(origin, endpoint);
				if(hit != null) intercept = hit.hitVec;
			}
		}

		// If the ray trace hit the entity...
		if(intercept != null){
			// Decides whether the entity that was hit is the closest so far, and if so, overwrites the old one.
			float currentHitDistance = (float)intercept.distanceTo(origin);
			float closestHitDistance = (float)closestHitPosition.distanceTo(origin);
			if(currentHitDistance < closestHitDistance){
				closestHitEntity = entity;
				closestHitPosition = intercept;
			}
		}
	}

	// If the ray trace hit an entity, return that entity; otherwise return the result of the block ray trace.
	if(closestHitEntity != null){
		result = new RayTraceResult(closestHitEntity, closestHitPosition);
	}

	return result;
}

public static RayTraceResult standardEntityRayTrace(World world, Entity entity, double range, boolean hitLiquids){
	// This method does not apply an offset like ray spells do, since it is not desirable in most other use cases.
	Vec3d origin = entity.getPositionEyes(1);
	Vec3d endpoint = origin.add(entity.getLookVec().scale(range));
	return rayTrace(world, origin, endpoint, 0, hitLiquids, false, false, Entity.class, ignoreEntityFilter(entity));
}

public static Predicate<Entity> ignoreEntityFilter(Entity entity){
	// Use deathTime > 0 so we still hit stuff that has *just* died, otherwise SpellRay#onEntityHit doesn't get
	// called on the client side when the entity is killed
	return e -> e == entity || (e instanceof EntityLivingBase && ((EntityLivingBase)e).deathTime > 0);
}

public void onUpdate(){

	super.onUpdate();

	if(ticksExisted == 1 && world.isRemote){
		Wizardry.proxy.playMovingSound(this, WizardrySounds.ENTITY_FORCEFIELD_AMBIENT, WizardrySounds.SPELLS, 0.5f, 1, true);
	}

	// New forcefield repulsion system:
	// Searches for all entities near the forcefield and determines where they will be next tick.
	// If they will be inside the forcefield next tick, sets their position and velocity such that they appear to
	// bounce off the forcefield and creates impact particle effects and sounds where they hit it

	List<Entity> targets = EntityUtils.getEntitiesWithinRadius(radius + SEARCH_BORDER_SIZE, posX, posY, posZ, world, Entity.class);

	targets.remove(this);
	targets.removeIf(t -> t instanceof EntityXPOrb); // Gets annoying since they're attracted to the player

	// Ring of the defender allows players to shoot through their own forcefields
	if(getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(),
			WizardryItems.ring_defender)){
		targets.removeIf(t -> t instanceof EntityMagicArrow && !this.isValidTarget(((EntityMagicArrow)t).getCaster())
							|| t instanceof EntityThrowable && !this.isValidTarget(((EntityThrowable)t).getThrower())
							|| t instanceof EntityArrow && !this.isValidTarget(((EntityArrow)t).shootingEntity));
	}

	for(Entity target : targets){

		if(this.isValidTarget(target)){

			Vec3d currentPos = Arrays.stream(GeometryUtils.getVertices(target.getEntityBoundingBox()))
					.min(Comparator.comparingDouble(v -> v.distanceTo(this.getPositionVector())))
					.orElse(target.getPositionVector()); // This will never happen, it's just here to make the compiler happy

			double currentDistance = target.getDistance(this);

			// Estimate the target's position next tick
			// We have to assume the same vertex is closest or the velocity will be wrong
			Vec3d nextTickPos = currentPos.add(target.motionX, target.motionY, target.motionZ);
			double nextTickDistance = nextTickPos.distanceTo(this.getPositionVector());

			boolean flag;

			if(EntityUtils.isLiving(target)){
				// Non-allied living entities shouldn't be inside at all
				flag = nextTickDistance <= radius;
			}else{
				// Non-living entities will bounce off if they hit the forcefield within the next tick...
				flag = (currentDistance > radius && nextTickDistance <= radius) // ...from the outside...
						|| (currentDistance < radius && nextTickDistance >= radius); // ...or from the inside
			}

			if(flag){

				// Ring of interdiction
				if(getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(),
						WizardryItems.ring_interdiction) && EntityUtils.isLiving(target)){
					target.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(),
							MagicDamage.DamageType.MAGIC), 1);
				}

				Vec3d targetRelativePos = currentPos.subtract(this.getPositionVector());

				double nudgeVelocity = this.contains(target) ? -0.1 : 0.1;
				if(EntityUtils.isLiving(target)) nudgeVelocity = 0.25;
				Vec3d extraVelocity = targetRelativePos.normalize().scale(nudgeVelocity);

				//Moved up the check by "19" so that way allied players aren't being moved out of the forcefield because
				//allied players aren't synced to client like minions. Minions are only synced because it's saved to their
				//entity data which is synced in their serialize/deserialize methods
				if(!world.isRemote){
					// ...make it bounce off!

					target.motionX = target.motionX * -BOUNCINESS + extraVelocity.x;
					target.motionY = target.motionY * -BOUNCINESS + extraVelocity.y;
					target.motionZ = target.motionZ * -BOUNCINESS + extraVelocity.z;

					// Prevents the forcefield bouncing things into the floor
					if(target.onGround && target.motionY < 0) target.motionY = 0.1;

					// How far the target needs to move towards the centre (negative means away from the centre)
					double distanceTowardsCentre = -(targetRelativePos.length() - radius) - (radius - nextTickDistance);
					Vec3d targetNewPos = target.getPositionVector().add(targetRelativePos.normalize().scale(distanceTowardsCentre));
					target.setPosition(targetNewPos.x, targetNewPos.y, targetNewPos.z);

					world.playSound(target.posX, target.posY, target.posZ, WizardrySounds.ENTITY_FORCEFIELD_DEFLECT,
							WizardrySounds.SPELLS, 0.3f, 1.3f, false);


					// Player motion is handled on that player's client so needs packets
					if(target instanceof EntityPlayerMP){
						((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
					}

					if (this.ticksExisted % 5 == 0) {
						this.lifetime = (int) (lifetime * 0.99);
					}

				}else{

					//This is a super lazy way to make sure the visual isn't playing for players and probably won't display the visual
					//for players if their velocity towards the forcefield is high. But it prevents the visual being spammed when ally player
					//is in forcefield so it's fine #19
					if(target instanceof EntityPlayer && target.getPositionVector().distanceTo(this.getPositionVector()) < this.getRadius()) return;

					Vec3d relativeImpactPos = targetRelativePos.normalize().scale(radius);

					float yaw = (float)Math.atan2(relativeImpactPos.x, -relativeImpactPos.z);
					float pitch = (float)Math.asin(relativeImpactPos.y/ radius);

					ParticleBuilder.create(Type.FLASH).pos(this.getPositionVector().add(relativeImpactPos))
					.time(6).face((float)(yaw * 180/Math.PI), (float)(pitch * 180/Math.PI))
					.clr(0.9f, 0.95f, 1).spawn(world);

					for(int i = 0; i < 12; i++){

						float yaw1 = yaw + 0.3f * (rand.nextFloat() - 0.5f) - (float)Math.PI/2;
						float pitch1 = pitch + 0.3f * (rand.nextFloat() - 0.5f);

						float brightness = rand.nextFloat();

						double r = radius + 0.05;
						double x = this.posX + r * MathHelper.cos(yaw1) * MathHelper.cos(pitch1);
						double y = this.posY + r * MathHelper.sin(pitch1);
						double z = this.posZ + r * MathHelper.sin(yaw1) * MathHelper.cos(pitch1);

						ParticleBuilder.create(Type.DUST).pos(x, y, z).time(6 + rand.nextInt(6))
						.face((float)(yaw1 * 180/Math.PI) + 90, (float)(pitch1 * 180/Math.PI)).scale(1.5f)
						.clr(0.7f + 0.3f * brightness, 0.85f + 0.15f * brightness, 1).spawn(world);
					}
				}
			}
		}
	}
}

package de.teamlapen.vampirism.common.world.entity;

